//! Rust mirror of `MidiInputResponse` / `MidiInputsResponse` / `MidiCueName`
//! (`backend/src/stagepilot/models/api.py`, `backend/src/stagepilot/core/midi.py`).
//!
//! TypeScript is generated by `cargo test -p stagepilot-core export_bindings` into
//! `generated/ts/` and committed. CI regenerates it and fails if
//! `git diff` is non-empty. `tests/python_contract.rs` also checks field names and optionality
//! against `contract/openapi.json`, so Rust and the Python API cannot drift apart silently.

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use ts_rs::TS;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum MidiCueName {
    StartNext,
    RestartCurrent,
    Previous,
    Next,
    ReloadPlan,
    StopTimer,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct MidiInputResponse {
    pub id: String,
    pub name: String,
    pub ambiguous: bool,
    pub selected: bool,
    pub connected: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct MidiInputsResponse {
    pub enabled: bool,
    pub channel: u8,
    pub note: u8,
    #[serde(default)]
    pub configured_input_name: Option<String>,
    #[serde(default)]
    pub selected_input_name: Option<String>,
    pub inputs: Vec<MidiInputResponse>,
    #[ts(as = "BTreeMap<MidiCueName, u8>")]
    pub mappings: BTreeMap<MidiCueName, u8>,
}
